-- Hotel Management System — Management Department module
-- database/seed-data.sql — demo/seed records (import AFTER schema.sql).
-- Dates are CURDATE()-relative, so the data always spans the last ~90 days
-- up to today, plus a few upcoming reservations. Safe to re-import after
-- truncating the seeded tables; on a live system, import once only.
USE hotel_management;

ON DUPLICATE KEY UPDATE full_name = VALUES(full_name);



ON DUPLICATE KEY UPDATE amount = VALUES(amount);








